#include "stdlib/stats/base/dists/halfnormal/mgf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/sqrt.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/math/base/special/exp.h"
#include "stdlib/math/base/special/erfc.h"

/**
* Evaluates the moment-generating function (MGF) for a half-normal
* distribution with scale parameter `sigma` at a value `t`.
*
* @param t      input value
* @param sigma  scale parameter
* @return       evaluated MGF
*
* @example
* double y = stdlib_base_dists_halfnormal_mgf( 1.0, 1.0 );
* // returns ~2.774
*/
double stdlib_base_dists_halfnormal_mgf( const double t, const double sigma ) {
	double inv_sqrt_two = 1.0 / stdlib_base_sqrt( 2.0 );;

	if (
		stdlib_base_is_nan( t ) ||
		stdlib_base_is_nan( sigma ) ||
		sigma <= 0.0
	) {
		return 0.0/0.0; // NaN
	}

	return stdlib_base_exp( 0.5 * stdlib_base_pow( sigma*t, 2.0 ) ) *
		( stdlib_base_erfc( -sigma * t * inv_sqrt_two  ) );
}
